// cuDTW-Ada | Phase 2 | SHFL_FULLDTW_GENERIC.cuh (v3 FINAL)
// AUTO-GENERATED — DO NOT EDIT. Run: python3 scripts/gen_generic_kernel.py
// FIX A: pre_loop skip save at r=1 (keep penalty_temp1=INFINITY)
// FIX B: k_stop = L_query+tgt_t+2; epilogue absorbed into main loop
#ifndef SHFL_FULLDTW_GENERIC_CUH
#define SHFL_FULLDTW_GENERIC_CUH

// ── Occupancy tuning knobs (item #6/#7) ──────────────────────────────────────
// WARPS_PER_BLOCK: independent sequences per block (each warp = one sequence).
// MIN_BLOCKS:      __launch_bounds__ second arg — min resident blocks/SM the
//                  compiler must keep feasible (caps registers accordingly).
//
// MEASURED on RTX 4090 (sm_89), tiled K=64, Lq=395 Ls=4437 N=65536, kernel-only:
//   register-resident, WPB=8, no cap   : 204 reg,  17% occ → 4152 GCUPS  (FAST)
//   __ldg subject,      WPB=8, no cap   : 153 reg,  17% occ →  347 GCUPS
//   __ldg, forced 33% occ (MIN_BLOCKS=2): 128 reg,  33% occ →  336 GCUPS
//   __ldg, forced 50% occ (MIN_BLOCKS=3):  80 reg,  50% occ →  306 GCUPS
// Conclusion: this is a per-warp recurrence-latency-bound kernel, NOT occupancy
// bound. Keeping the subject row + penalties in registers is THE win; __ldg and
// forced register caps both regress ~12×. WPB=1 and WPB=8 are a measured WASH
// (both ~8 warps/SM, ~4150 GCUPS, within run-to-run noise); --maxrregcount below
// the __launch_bounds__-implied cap is non-binding (regs stay ~204). Default to
// WPB=1 for simpler launch geometry. Override via -D only to re-experiment.
#ifndef CUDTW_GENERIC_WARPS_PER_BLOCK
#define CUDTW_GENERIC_WARPS_PER_BLOCK 1
#endif
#ifndef CUDTW_GENERIC_MIN_BLOCKS
#define CUDTW_GENERIC_MIN_BLOCKS 1
#endif
// Subject access mode (item #7): 0 = cache subject row in registers,
// 1 = read via __ldg at point of use (frees ~K registers, raises occupancy).
#ifndef CUDTW_GENERIC_LDG_SUBJECT
#define CUDTW_GENERIC_LDG_SUBJECT 0
#endif

// K=  2 | L≤63
template<typename index_t, typename value_t> __global__
__launch_bounds__(32*CUDTW_GENERIC_WARPS_PER_BLOCK, CUDTW_GENERIC_MIN_BLOCKS)
void shfl_FullDTW_K2(
    const value_t* __restrict__ Subject,
    value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride)
{
    // Multi-warp blocks (item #6): each warp handles one independent
    // sequence. lane = intra-warp 0..31; warp_in_block selects the warp.
    // All __shfl_*_sync below use width=32, so they stay warp-local.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid = lane;
    const index_t l = thid;
    const index_t WARP_SIZE = 32;
    const index_t base = blid * padded_stride;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_left = INFINITY;
    value_t penalty_diag = 0;
    value_t penalty_temp0, penalty_temp1;

    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
    }

#if CUDTW_GENERIC_LDG_SUBJECT
    #define SV0  ((l==0)?(value_t)0:__ldg(&Subject[base+2*l-1]))
    #define SV1  (__ldg(&Subject[base+2*l+0]))
    #define SV2  (__ldg(&Subject[base+2*l+1]))
#else
    const value_t subject_value0 = (l==0)?(value_t)0:Subject[base+2*l-1];
    const value_t subject_value1 = Subject[base+2*l+0];
    const value_t subject_value2 = Subject[base+2*l+1];
    #define SV0  subject_value0
    #define SV1  subject_value1
    #define SV2  subject_value2
#endif

    // Result position (needed for loop bound — FIX B)
    const int tgt_t = (int)(L_subject / 2);
    const int tgt_r = (int)(L_subject % 2);
    // Thread tgt_t processes row L_query-1 at k = L_query+tgt_t+1.
    // Loop runs until that step. No epilogue needed.
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t counter = 1;
    value_t query_value = INFINITY;
    value_t new_query_value = cQuery[thid];
    if (thid == 0) query_value = new_query_value;
    if (thid == 0) penalty_here1 = (value_t)0;  // free start
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = INFINITY;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
    query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
    if (thid == 0) query_value = new_query_value;
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
    counter++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here1, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop — runs until tgt_t computes row L_query-1 (FIX B)
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (counter % 32 == 0) new_query_value = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
        if (thid == 0) query_value = new_query_value;
        new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
        counter++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here1, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    // Extract dp[L_query-1][L_subject-1] from (tgt_t, tgt_r)
    {
        value_t result = (value_t)0;
        if ((int)thid == tgt_t) {
            if (tgt_r == 0) result = penalty_here0;
            if (tgt_r == 1) result = penalty_here1;
        }
        result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
        if (thid == 0) Dist[blid] = result;
    }
}
#undef SV0
#undef SV1
#undef SV2

