#if CUDTW_GENERIC_LDG_SUBJECT
    #define SV0  ((l==0)?(value_t)0:__ldg(&Subject[base+11*l-1]))
    #define SV1  (__ldg(&Subject[base+11*l+0]))
    #define SV2  (__ldg(&Subject[base+11*l+1]))
    #define SV3  (__ldg(&Subject[base+11*l+2]))
