    // Multi-warp blocks (item #6): each warp handles one independent
    // sequence. lane = intra-warp 0..31; warp_in_block selects the warp.
    // All __shfl_*_sync below use width=32, so they stay warp-local.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid = lane;
    const index_t l = thid;
    const index_t WARP_SIZE = 32;
    const index_t base = blid * padded_stride;

    value_t penalty_here0 = INFINITY;
    value_t penalty_here1 = INFINITY;
    value_t penalty_here2 = INFINITY;
    value_t penalty_here3 = INFINITY;
    value_t penalty_here4 = INFINITY;
    value_t penalty_here5 = INFINITY;
    value_t penalty_here6 = INFINITY;
    value_t penalty_here7 = INFINITY;
    value_t penalty_here8 = INFINITY;
    value_t penalty_here9 = INFINITY;
    value_t penalty_here10 = INFINITY;
    value_t penalty_here11 = INFINITY;
    value_t penalty_here12 = INFINITY;
    value_t penalty_here13 = INFINITY;
    value_t penalty_here14 = INFINITY;
    value_t penalty_left = INFINITY;
    value_t penalty_diag = 0;
    value_t penalty_temp0, penalty_temp1;

    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
    }

#if CUDTW_GENERIC_LDG_SUBJECT
    #define SV0  ((l==0)?(value_t)0:__ldg(&Subject[base+15*l-1]))
    #define SV1  (__ldg(&Subject[base+15*l+0]))
    #define SV2  (__ldg(&Subject[base+15*l+1]))
    #define SV3  (__ldg(&Subject[base+15*l+2]))
    #define SV4  (__ldg(&Subject[base+15*l+3]))
    #define SV5  (__ldg(&Subject[base+15*l+4]))
    #define SV6  (__ldg(&Subject[base+15*l+5]))
    #define SV7  (__ldg(&Subject[base+15*l+6]))
    #define SV8  (__ldg(&Subject[base+15*l+7]))
    #define SV9  (__ldg(&Subject[base+15*l+8]))
    #define SV10  (__ldg(&Subject[base+15*l+9]))
    #define SV11  (__ldg(&Subject[base+15*l+10]))
    #define SV12  (__ldg(&Subject[base+15*l+11]))
    #define SV13  (__ldg(&Subject[base+15*l+12]))
    #define SV14  (__ldg(&Subject[base+15*l+13]))
    #define SV15  (__ldg(&Subject[base+15*l+14]))
#else
    const value_t subject_value0 = (l==0)?(value_t)0:Subject[base+15*l-1];
    const value_t subject_value1 = Subject[base+15*l+0];
    const value_t subject_value2 = Subject[base+15*l+1];
    const value_t subject_value3 = Subject[base+15*l+2];
    const value_t subject_value4 = Subject[base+15*l+3];
    const value_t subject_value5 = Subject[base+15*l+4];
    const value_t subject_value6 = Subject[base+15*l+5];
    const value_t subject_value7 = Subject[base+15*l+6];
    const value_t subject_value8 = Subject[base+15*l+7];
    const value_t subject_value9 = Subject[base+15*l+8];
    const value_t subject_value10 = Subject[base+15*l+9];
    const value_t subject_value11 = Subject[base+15*l+10];
    const value_t subject_value12 = Subject[base+15*l+11];
    const value_t subject_value13 = Subject[base+15*l+12];
    const value_t subject_value14 = Subject[base+15*l+13];
    const value_t subject_value15 = Subject[base+15*l+14];
    #define SV0  subject_value0
    #define SV1  subject_value1
    #define SV2  subject_value2
    #define SV3  subject_value3
    #define SV4  subject_value4
    #define SV5  subject_value5
    #define SV6  subject_value6
    #define SV7  subject_value7
    #define SV8  subject_value8
    #define SV9  subject_value9
    #define SV10  subject_value10
    #define SV11  subject_value11
    #define SV12  subject_value12
    #define SV13  subject_value13
    #define SV14  subject_value14
    #define SV15  subject_value15
#endif

    // Result position (needed for loop bound — FIX B)
    const int tgt_t = (int)(L_subject / 15);
    const int tgt_r = (int)(L_subject % 15);
    // Thread tgt_t processes row L_query-1 at k = L_query+tgt_t+1.
    // Loop runs until that step. No epilogue needed.
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t counter = 1;
    value_t query_value = INFINITY;
    value_t new_query_value = cQuery[thid];
    if (thid == 0) query_value = new_query_value;
    if (thid == 0) penalty_here1 = (value_t)0;  // free start
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = INFINITY;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (query_value-SV2)*(query_value-SV2)+min(penalty_here1,min(penalty_here2,penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (query_value-SV3)*(query_value-SV3)+min(penalty_here2,min(penalty_here3,penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (query_value-SV4)*(query_value-SV4)+min(penalty_here3,min(penalty_here4,penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (query_value-SV5)*(query_value-SV5)+min(penalty_here4,min(penalty_here5,penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (query_value-SV6)*(query_value-SV6)+min(penalty_here5,min(penalty_here6,penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (query_value-SV7)*(query_value-SV7)+min(penalty_here6,min(penalty_here7,penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (query_value-SV8)*(query_value-SV8)+min(penalty_here7,min(penalty_here8,penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (query_value-SV9)*(query_value-SV9)+min(penalty_here8,min(penalty_here9,penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (query_value-SV10)*(query_value-SV10)+min(penalty_here9,min(penalty_here10,penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (query_value-SV11)*(query_value-SV11)+min(penalty_here10,min(penalty_here11,penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (query_value-SV12)*(query_value-SV12)+min(penalty_here11,min(penalty_here12,penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (query_value-SV13)*(query_value-SV13)+min(penalty_here12,min(penalty_here13,penalty_temp0));
        penalty_here14 = (query_value-SV14)*(query_value-SV14)+min(penalty_here13,min(penalty_here14,penalty_temp1));
    query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
    if (thid == 0) query_value = new_query_value;
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
    counter++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here14, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop — runs until tgt_t computes row L_query-1 (FIX B)
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (counter % 32 == 0) new_query_value = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = penalty_here1;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (query_value-SV2)*(query_value-SV2)+min(penalty_here1,min(penalty_here2,penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (query_value-SV3)*(query_value-SV3)+min(penalty_here2,min(penalty_here3,penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (query_value-SV4)*(query_value-SV4)+min(penalty_here3,min(penalty_here4,penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (query_value-SV5)*(query_value-SV5)+min(penalty_here4,min(penalty_here5,penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (query_value-SV6)*(query_value-SV6)+min(penalty_here5,min(penalty_here6,penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (query_value-SV7)*(query_value-SV7)+min(penalty_here6,min(penalty_here7,penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (query_value-SV8)*(query_value-SV8)+min(penalty_here7,min(penalty_here8,penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (query_value-SV9)*(query_value-SV9)+min(penalty_here8,min(penalty_here9,penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (query_value-SV10)*(query_value-SV10)+min(penalty_here9,min(penalty_here10,penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (query_value-SV11)*(query_value-SV11)+min(penalty_here10,min(penalty_here11,penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (query_value-SV12)*(query_value-SV12)+min(penalty_here11,min(penalty_here12,penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (query_value-SV13)*(query_value-SV13)+min(penalty_here12,min(penalty_here13,penalty_temp0));
        penalty_here14 = (query_value-SV14)*(query_value-SV14)+min(penalty_here13,min(penalty_here14,penalty_temp1));
        query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
        if (thid == 0) query_value = new_query_value;
        new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
        counter++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here14, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    // Extract dp[L_query-1][L_subject-1] from (tgt_t, tgt_r)
    {
        value_t result = (value_t)0;
        if ((int)thid == tgt_t) {
            if (tgt_r == 0) result = penalty_here0;
            if (tgt_r == 1) result = penalty_here1;
            if (tgt_r == 2) result = penalty_here2;
            if (tgt_r == 3) result = penalty_here3;
            if (tgt_r == 4) result = penalty_here4;
            if (tgt_r == 5) result = penalty_here5;
            if (tgt_r == 6) result = penalty_here6;
            if (tgt_r == 7) result = penalty_here7;
            if (tgt_r == 8) result = penalty_here8;
            if (tgt_r == 9) result = penalty_here9;
            if (tgt_r == 10) result = penalty_here10;
            if (tgt_r == 11) result = penalty_here11;
            if (tgt_r == 12) result = penalty_here12;
            if (tgt_r == 13) result = penalty_here13;
            if (tgt_r == 14) result = penalty_here14;
        }
        result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
        if (thid == 0) Dist[blid] = result;
    }
}
#undef SV0
#undef SV1
#undef SV2
#undef SV3
#undef SV4
#undef SV5
#undef SV6
#undef SV7
#undef SV8
#undef SV9
#undef SV10
#undef SV11
#undef SV12
#undef SV13
#undef SV14
#undef SV15

// K= 16 | L≤511
template<typename index_t, typename value_t> __global__
__launch_bounds__(32*CUDTW_GENERIC_WARPS_PER_BLOCK, CUDTW_GENERIC_MIN_BLOCKS)
void shfl_FullDTW_K16(
    const value_t* __restrict__ Subject,
    value_t* __restrict__ Dist,
    index_t N, index_t L_query, index_t L_subject, index_t padded_stride)
{
    // Multi-warp blocks (item #6): each warp handles one independent
    // sequence. lane = intra-warp 0..31; warp_in_block selects the warp.
    // All __shfl_*_sync below use width=32, so they stay warp-local.
    const index_t lane = threadIdx.x & 31u;
    const index_t warp_in_block = threadIdx.x >> 5;
    const index_t blid = (index_t)blockIdx.x * (blockDim.x >> 5) + warp_in_block;
    if (blid >= N) return;
    const index_t thid = lane;
    const index_t l = thid;
