        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
    }

#if CUDTW_GENERIC_LDG_SUBJECT
    #define SV0  ((l==0)?(value_t)0:__ldg(&Subject[base+16*l-1]))
    #define SV1  (__ldg(&Subject[base+16*l+0]))
    #define SV2  (__ldg(&Subject[base+16*l+1]))
    #define SV3  (__ldg(&Subject[base+16*l+2]))
    #define SV4  (__ldg(&Subject[base+16*l+3]))
    #define SV5  (__ldg(&Subject[base+16*l+4]))
    #define SV6  (__ldg(&Subject[base+16*l+5]))
    #define SV7  (__ldg(&Subject[base+16*l+6]))
    #define SV8  (__ldg(&Subject[base+16*l+7]))
    #define SV9  (__ldg(&Subject[base+16*l+8]))
    #define SV10  (__ldg(&Subject[base+16*l+9]))
    #define SV11  (__ldg(&Subject[base+16*l+10]))
    #define SV12  (__ldg(&Subject[base+16*l+11]))
    #define SV13  (__ldg(&Subject[base+16*l+12]))
    #define SV14  (__ldg(&Subject[base+16*l+13]))
    #define SV15  (__ldg(&Subject[base+16*l+14]))
    #define SV16  (__ldg(&Subject[base+16*l+15]))
#else
    const value_t subject_value0 = (l==0)?(value_t)0:Subject[base+16*l-1];
    const value_t subject_value1 = Subject[base+16*l+0];
    const value_t subject_value2 = Subject[base+16*l+1];
    const value_t subject_value3 = Subject[base+16*l+2];
    const value_t subject_value4 = Subject[base+16*l+3];
    const value_t subject_value5 = Subject[base+16*l+4];
    const value_t subject_value6 = Subject[base+16*l+5];
    const value_t subject_value7 = Subject[base+16*l+6];
    const value_t subject_value8 = Subject[base+16*l+7];
    const value_t subject_value9 = Subject[base+16*l+8];
    const value_t subject_value10 = Subject[base+16*l+9];
    const value_t subject_value11 = Subject[base+16*l+10];
    const value_t subject_value12 = Subject[base+16*l+11];
    const value_t subject_value13 = Subject[base+16*l+12];
    const value_t subject_value14 = Subject[base+16*l+13];
    const value_t subject_value15 = Subject[base+16*l+14];
    const value_t subject_value16 = Subject[base+16*l+15];
    #define SV0  subject_value0
    #define SV1  subject_value1
    #define SV2  subject_value2
    #define SV3  subject_value3
    #define SV4  subject_value4
    #define SV5  subject_value5
    #define SV6  subject_value6
    #define SV7  subject_value7
    #define SV8  subject_value8
    #define SV9  subject_value9
    #define SV10  subject_value10
    #define SV11  subject_value11
    #define SV12  subject_value12
    #define SV13  subject_value13
    #define SV14  subject_value14
    #define SV15  subject_value15
    #define SV16  subject_value16
