    if (thid == 0) penalty_left = INFINITY;

    // Main loop — runs until tgt_t computes row L_query-1 (FIX B)
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (counter % 32 == 0) new_query_value = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = penalty_here1;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (query_value-SV2)*(query_value-SV2)+min(penalty_here1,min(penalty_here2,penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (query_value-SV3)*(query_value-SV3)+min(penalty_here2,min(penalty_here3,penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (query_value-SV4)*(query_value-SV4)+min(penalty_here3,min(penalty_here4,penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (query_value-SV5)*(query_value-SV5)+min(penalty_here4,min(penalty_here5,penalty_temp0));
        penalty_temp0 = penalty_here6;
