    const value_t subject_value10 = Subject[base+20*l+9];
    const value_t subject_value11 = Subject[base+20*l+10];
    const value_t subject_value12 = Subject[base+20*l+11];
    const value_t subject_value13 = Subject[base+20*l+12];
    const value_t subject_value14 = Subject[base+20*l+13];
    const value_t subject_value15 = Subject[base+20*l+14];
    const value_t subject_value16 = Subject[base+20*l+15];
    const value_t subject_value17 = Subject[base+20*l+16];
    const value_t subject_value18 = Subject[base+20*l+17];
    const value_t subject_value19 = Subject[base+20*l+18];
    const value_t subject_value20 = Subject[base+20*l+19];
    #define SV0  subject_value0
    #define SV1  subject_value1
    #define SV2  subject_value2
    #define SV3  subject_value3
    #define SV4  subject_value4
    #define SV5  subject_value5
    #define SV6  subject_value6
    #define SV7  subject_value7
    #define SV8  subject_value8
