        penalty_here21 = (query_value-SV21)*(query_value-SV21)+min(penalty_here20,min(penalty_here21,penalty_temp0));
    query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
    if (thid == 0) query_value = new_query_value;
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
    counter++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here21, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop — runs until tgt_t computes row L_query-1 (FIX B)
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
