    value_t new_query_value = cQuery[thid];
    if (thid == 0) query_value = new_query_value;
    if (thid == 0) penalty_here1 = (value_t)0;  // free start
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = INFINITY;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
