    #define SV20  subject_value20
    #define SV21  subject_value21
    #define SV22  subject_value22
    #define SV23  subject_value23
    #define SV24  subject_value24
    #define SV25  subject_value25
#endif

    // Result position (needed for loop bound — FIX B)
    const int tgt_t = (int)(L_subject / 25);
    const int tgt_r = (int)(L_subject % 25);
    // Thread tgt_t processes row L_query-1 at k = L_query+tgt_t+1.
    // Loop runs until that step. No epilogue needed.
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t counter = 1;
    value_t query_value = INFINITY;
    value_t new_query_value = cQuery[thid];
    if (thid == 0) query_value = new_query_value;
    if (thid == 0) penalty_here1 = (value_t)0;  // free start
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = INFINITY;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (query_value-SV2)*(query_value-SV2)+min(penalty_here1,min(penalty_here2,penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (query_value-SV3)*(query_value-SV3)+min(penalty_here2,min(penalty_here3,penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (query_value-SV4)*(query_value-SV4)+min(penalty_here3,min(penalty_here4,penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (query_value-SV5)*(query_value-SV5)+min(penalty_here4,min(penalty_here5,penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (query_value-SV6)*(query_value-SV6)+min(penalty_here5,min(penalty_here6,penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (query_value-SV7)*(query_value-SV7)+min(penalty_here6,min(penalty_here7,penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (query_value-SV8)*(query_value-SV8)+min(penalty_here7,min(penalty_here8,penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (query_value-SV9)*(query_value-SV9)+min(penalty_here8,min(penalty_here9,penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (query_value-SV10)*(query_value-SV10)+min(penalty_here9,min(penalty_here10,penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (query_value-SV11)*(query_value-SV11)+min(penalty_here10,min(penalty_here11,penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (query_value-SV12)*(query_value-SV12)+min(penalty_here11,min(penalty_here12,penalty_temp1));
        penalty_temp1 = penalty_here13;
        penalty_here13 = (query_value-SV13)*(query_value-SV13)+min(penalty_here12,min(penalty_here13,penalty_temp0));
        penalty_temp0 = penalty_here14;
        penalty_here14 = (query_value-SV14)*(query_value-SV14)+min(penalty_here13,min(penalty_here14,penalty_temp1));
        penalty_temp1 = penalty_here15;
        penalty_here15 = (query_value-SV15)*(query_value-SV15)+min(penalty_here14,min(penalty_here15,penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (query_value-SV16)*(query_value-SV16)+min(penalty_here15,min(penalty_here16,penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (query_value-SV17)*(query_value-SV17)+min(penalty_here16,min(penalty_here17,penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (query_value-SV18)*(query_value-SV18)+min(penalty_here17,min(penalty_here18,penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (query_value-SV19)*(query_value-SV19)+min(penalty_here18,min(penalty_here19,penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (query_value-SV20)*(query_value-SV20)+min(penalty_here19,min(penalty_here20,penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (query_value-SV21)*(query_value-SV21)+min(penalty_here20,min(penalty_here21,penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (query_value-SV22)*(query_value-SV22)+min(penalty_here21,min(penalty_here22,penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (query_value-SV23)*(query_value-SV23)+min(penalty_here22,min(penalty_here23,penalty_temp0));
        penalty_here24 = (query_value-SV24)*(query_value-SV24)+min(penalty_here23,min(penalty_here24,penalty_temp1));
    query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
    if (thid == 0) query_value = new_query_value;
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
    counter++;
    penalty_diag = penalty_left;
    penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here24, 1, 32);
    if (thid == 0) penalty_left = INFINITY;

    // Main loop — runs until tgt_t computes row L_query-1 (FIX B)
    for (index_t k = 3; k < k_stop; k++) {
        const index_t i = k - l;
        if (counter % 32 == 0) new_query_value = cQuery[i + 2*thid - 1];
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = penalty_here1;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (query_value-SV2)*(query_value-SV2)+min(penalty_here1,min(penalty_here2,penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (query_value-SV3)*(query_value-SV3)+min(penalty_here2,min(penalty_here3,penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (query_value-SV4)*(query_value-SV4)+min(penalty_here3,min(penalty_here4,penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (query_value-SV5)*(query_value-SV5)+min(penalty_here4,min(penalty_here5,penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (query_value-SV6)*(query_value-SV6)+min(penalty_here5,min(penalty_here6,penalty_temp1));
        penalty_temp1 = penalty_here7;
        penalty_here7 = (query_value-SV7)*(query_value-SV7)+min(penalty_here6,min(penalty_here7,penalty_temp0));
        penalty_temp0 = penalty_here8;
        penalty_here8 = (query_value-SV8)*(query_value-SV8)+min(penalty_here7,min(penalty_here8,penalty_temp1));
        penalty_temp1 = penalty_here9;
        penalty_here9 = (query_value-SV9)*(query_value-SV9)+min(penalty_here8,min(penalty_here9,penalty_temp0));
        penalty_temp0 = penalty_here10;
        penalty_here10 = (query_value-SV10)*(query_value-SV10)+min(penalty_here9,min(penalty_here10,penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (query_value-SV11)*(query_value-SV11)+min(penalty_here10,min(penalty_here11,penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (query_value-SV12)*(query_value-SV12)+min(penalty_here11,min(penalty_here12,penalty_temp1));
        penalty_temp1 = penalty_here13;
