#else
    const value_t subject_value0 = (l==0)?(value_t)0:Subject[base+27*l-1];
    const value_t subject_value1 = Subject[base+27*l+0];
    const value_t subject_value2 = Subject[base+27*l+1];
    const value_t subject_value3 = Subject[base+27*l+2];
    const value_t subject_value4 = Subject[base+27*l+3];
    const value_t subject_value5 = Subject[base+27*l+4];
