        penalty_here10 = (query_value-SV10)*(query_value-SV10)+min(penalty_here9,min(penalty_here10,penalty_temp1));
        penalty_temp1 = penalty_here11;
        penalty_here11 = (query_value-SV11)*(query_value-SV11)+min(penalty_here10,min(penalty_here11,penalty_temp0));
        penalty_temp0 = penalty_here12;
        penalty_here12 = (query_value-SV12)*(query_value-SV12)+min(penalty_here11,min(penalty_here12,penalty_temp1));
