        penalty_temp1 = penalty_here15;
        penalty_here15 = (query_value-SV15)*(query_value-SV15)+min(penalty_here14,min(penalty_here15,penalty_temp0));
        penalty_temp0 = penalty_here16;
        penalty_here16 = (query_value-SV16)*(query_value-SV16)+min(penalty_here15,min(penalty_here16,penalty_temp1));
        penalty_temp1 = penalty_here17;
        penalty_here17 = (query_value-SV17)*(query_value-SV17)+min(penalty_here16,min(penalty_here17,penalty_temp0));
        penalty_temp0 = penalty_here18;
        penalty_here18 = (query_value-SV18)*(query_value-SV18)+min(penalty_here17,min(penalty_here18,penalty_temp1));
        penalty_temp1 = penalty_here19;
        penalty_here19 = (query_value-SV19)*(query_value-SV19)+min(penalty_here18,min(penalty_here19,penalty_temp0));
        penalty_temp0 = penalty_here20;
        penalty_here20 = (query_value-SV20)*(query_value-SV20)+min(penalty_here19,min(penalty_here20,penalty_temp1));
        penalty_temp1 = penalty_here21;
        penalty_here21 = (query_value-SV21)*(query_value-SV21)+min(penalty_here20,min(penalty_here21,penalty_temp0));
        penalty_temp0 = penalty_here22;
        penalty_here22 = (query_value-SV22)*(query_value-SV22)+min(penalty_here21,min(penalty_here22,penalty_temp1));
        penalty_temp1 = penalty_here23;
        penalty_here23 = (query_value-SV23)*(query_value-SV23)+min(penalty_here22,min(penalty_here23,penalty_temp0));
        penalty_temp0 = penalty_here24;
        penalty_here24 = (query_value-SV24)*(query_value-SV24)+min(penalty_here23,min(penalty_here24,penalty_temp1));
        penalty_temp1 = penalty_here25;
        penalty_here25 = (query_value-SV25)*(query_value-SV25)+min(penalty_here24,min(penalty_here25,penalty_temp0));
        penalty_temp0 = penalty_here26;
        penalty_here26 = (query_value-SV26)*(query_value-SV26)+min(penalty_here25,min(penalty_here26,penalty_temp1));
        penalty_temp1 = penalty_here27;
        penalty_here27 = (query_value-SV27)*(query_value-SV27)+min(penalty_here26,min(penalty_here27,penalty_temp0));
        penalty_temp0 = penalty_here28;
        penalty_here28 = (query_value-SV28)*(query_value-SV28)+min(penalty_here27,min(penalty_here28,penalty_temp1));
        penalty_temp1 = penalty_here29;
        penalty_here29 = (query_value-SV29)*(query_value-SV29)+min(penalty_here28,min(penalty_here29,penalty_temp0));
        penalty_here30 = (query_value-SV30)*(query_value-SV30)+min(penalty_here29,min(penalty_here30,penalty_temp1));
        query_value = __shfl_up_sync(0xFFFFFFFF, query_value, 1, 32);
        if (thid == 0) query_value = new_query_value;
        new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);
        counter++;
        penalty_diag = penalty_left;
        penalty_left = __shfl_up_sync(0xFFFFFFFF, penalty_here30, 1, 32);
        if (thid == 0) penalty_left = INFINITY;
    }

    // Extract dp[L_query-1][L_subject-1] from (tgt_t, tgt_r)
    {
        value_t result = (value_t)0;
        if ((int)thid == tgt_t) {
            if (tgt_r == 0) result = penalty_here0;
            if (tgt_r == 1) result = penalty_here1;
            if (tgt_r == 2) result = penalty_here2;
            if (tgt_r == 3) result = penalty_here3;
            if (tgt_r == 4) result = penalty_here4;
            if (tgt_r == 5) result = penalty_here5;
            if (tgt_r == 6) result = penalty_here6;
            if (tgt_r == 7) result = penalty_here7;
            if (tgt_r == 8) result = penalty_here8;
            if (tgt_r == 9) result = penalty_here9;
            if (tgt_r == 10) result = penalty_here10;
            if (tgt_r == 11) result = penalty_here11;
            if (tgt_r == 12) result = penalty_here12;
            if (tgt_r == 13) result = penalty_here13;
            if (tgt_r == 14) result = penalty_here14;
            if (tgt_r == 15) result = penalty_here15;
            if (tgt_r == 16) result = penalty_here16;
            if (tgt_r == 17) result = penalty_here17;
            if (tgt_r == 18) result = penalty_here18;
            if (tgt_r == 19) result = penalty_here19;
            if (tgt_r == 20) result = penalty_here20;
            if (tgt_r == 21) result = penalty_here21;
            if (tgt_r == 22) result = penalty_here22;
            if (tgt_r == 23) result = penalty_here23;
            if (tgt_r == 24) result = penalty_here24;
            if (tgt_r == 25) result = penalty_here25;
            if (tgt_r == 26) result = penalty_here26;
            if (tgt_r == 27) result = penalty_here27;
            if (tgt_r == 28) result = penalty_here28;
            if (tgt_r == 29) result = penalty_here29;
            if (tgt_r == 30) result = penalty_here30;
        }
        result = __shfl_sync(0xFFFFFFFF, result, tgt_t);
        if (thid == 0) Dist[blid] = result;
    }
}
