    value_t penalty_here21 = INFINITY;
    value_t penalty_here22 = INFINITY;
    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_here25 = INFINITY;
    value_t penalty_here26 = INFINITY;
    value_t penalty_here27 = INFINITY;
    value_t penalty_here28 = INFINITY;
    value_t penalty_here29 = INFINITY;
    value_t penalty_here30 = INFINITY;
    value_t penalty_here31 = INFINITY;
    value_t penalty_left = INFINITY;
    value_t penalty_diag = 0;
    value_t penalty_temp0, penalty_temp1;

    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
        penalty_here7 = INFINITY;
        penalty_here8 = INFINITY;
        penalty_here9 = INFINITY;
        penalty_here10 = INFINITY;
        penalty_here11 = INFINITY;
        penalty_here12 = INFINITY;
        penalty_here13 = INFINITY;
        penalty_here14 = INFINITY;
        penalty_here15 = INFINITY;
        penalty_here16 = INFINITY;
        penalty_here17 = INFINITY;
        penalty_here18 = INFINITY;
        penalty_here19 = INFINITY;
        penalty_here20 = INFINITY;
        penalty_here21 = INFINITY;
        penalty_here22 = INFINITY;
        penalty_here23 = INFINITY;
        penalty_here24 = INFINITY;
        penalty_here25 = INFINITY;
        penalty_here26 = INFINITY;
        penalty_here27 = INFINITY;
        penalty_here28 = INFINITY;
        penalty_here29 = INFINITY;
        penalty_here30 = INFINITY;
        penalty_here31 = INFINITY;
    }

#if CUDTW_GENERIC_LDG_SUBJECT
    #define SV0  ((l==0)?(value_t)0:__ldg(&Subject[base+32*l-1]))
    #define SV1  (__ldg(&Subject[base+32*l+0]))
    #define SV2  (__ldg(&Subject[base+32*l+1]))
    #define SV3  (__ldg(&Subject[base+32*l+2]))
    #define SV4  (__ldg(&Subject[base+32*l+3]))
    #define SV5  (__ldg(&Subject[base+32*l+4]))
    #define SV6  (__ldg(&Subject[base+32*l+5]))
    #define SV7  (__ldg(&Subject[base+32*l+6]))
    #define SV8  (__ldg(&Subject[base+32*l+7]))
    #define SV9  (__ldg(&Subject[base+32*l+8]))
    #define SV10  (__ldg(&Subject[base+32*l+9]))
    #define SV11  (__ldg(&Subject[base+32*l+10]))
    #define SV12  (__ldg(&Subject[base+32*l+11]))
    #define SV13  (__ldg(&Subject[base+32*l+12]))
    #define SV14  (__ldg(&Subject[base+32*l+13]))
    #define SV15  (__ldg(&Subject[base+32*l+14]))
    #define SV16  (__ldg(&Subject[base+32*l+15]))
    #define SV17  (__ldg(&Subject[base+32*l+16]))
    #define SV18  (__ldg(&Subject[base+32*l+17]))
    #define SV19  (__ldg(&Subject[base+32*l+18]))
    #define SV20  (__ldg(&Subject[base+32*l+19]))
    #define SV21  (__ldg(&Subject[base+32*l+20]))
    #define SV22  (__ldg(&Subject[base+32*l+21]))
    #define SV23  (__ldg(&Subject[base+32*l+22]))
    #define SV24  (__ldg(&Subject[base+32*l+23]))
    #define SV25  (__ldg(&Subject[base+32*l+24]))
    #define SV26  (__ldg(&Subject[base+32*l+25]))
    #define SV27  (__ldg(&Subject[base+32*l+26]))
    #define SV28  (__ldg(&Subject[base+32*l+27]))
    #define SV29  (__ldg(&Subject[base+32*l+28]))
    #define SV30  (__ldg(&Subject[base+32*l+29]))
    #define SV31  (__ldg(&Subject[base+32*l+30]))
    #define SV32  (__ldg(&Subject[base+32*l+31]))
#else
    const value_t subject_value0 = (l==0)?(value_t)0:Subject[base+32*l-1];
    const value_t subject_value1 = Subject[base+32*l+0];
    const value_t subject_value2 = Subject[base+32*l+1];
    const value_t subject_value3 = Subject[base+32*l+2];
    const value_t subject_value4 = Subject[base+32*l+3];
    const value_t subject_value5 = Subject[base+32*l+4];
    const value_t subject_value6 = Subject[base+32*l+5];
    const value_t subject_value7 = Subject[base+32*l+6];
    const value_t subject_value8 = Subject[base+32*l+7];
    const value_t subject_value9 = Subject[base+32*l+8];
    const value_t subject_value10 = Subject[base+32*l+9];
    const value_t subject_value11 = Subject[base+32*l+10];
    const value_t subject_value12 = Subject[base+32*l+11];
    const value_t subject_value13 = Subject[base+32*l+12];
    const value_t subject_value14 = Subject[base+32*l+13];
    const value_t subject_value15 = Subject[base+32*l+14];
    const value_t subject_value16 = Subject[base+32*l+15];
    const value_t subject_value17 = Subject[base+32*l+16];
    const value_t subject_value18 = Subject[base+32*l+17];
    const value_t subject_value19 = Subject[base+32*l+18];
    const value_t subject_value20 = Subject[base+32*l+19];
    const value_t subject_value21 = Subject[base+32*l+20];
    const value_t subject_value22 = Subject[base+32*l+21];
    const value_t subject_value23 = Subject[base+32*l+22];
    const value_t subject_value24 = Subject[base+32*l+23];
    const value_t subject_value25 = Subject[base+32*l+24];
    const value_t subject_value26 = Subject[base+32*l+25];
    const value_t subject_value27 = Subject[base+32*l+26];
    const value_t subject_value28 = Subject[base+32*l+27];
    const value_t subject_value29 = Subject[base+32*l+28];
    const value_t subject_value30 = Subject[base+32*l+29];
    const value_t subject_value31 = Subject[base+32*l+30];
    const value_t subject_value32 = Subject[base+32*l+31];
    #define SV0  subject_value0
    #define SV1  subject_value1
    #define SV2  subject_value2
    #define SV3  subject_value3
    #define SV4  subject_value4
    #define SV5  subject_value5
    #define SV6  subject_value6
    #define SV7  subject_value7
    #define SV8  subject_value8
    #define SV9  subject_value9
    #define SV10  subject_value10
    #define SV11  subject_value11
    #define SV12  subject_value12
    #define SV13  subject_value13
    #define SV14  subject_value14
    #define SV15  subject_value15
    #define SV16  subject_value16
    #define SV17  subject_value17
    #define SV18  subject_value18
    #define SV19  subject_value19
    #define SV20  subject_value20
    #define SV21  subject_value21
    #define SV22  subject_value22
    #define SV23  subject_value23
    #define SV24  subject_value24
    #define SV25  subject_value25
    #define SV26  subject_value26
    #define SV27  subject_value27
    #define SV28  subject_value28
    #define SV29  subject_value29
    #define SV30  subject_value30
    #define SV31  subject_value31
    #define SV32  subject_value32
#endif

    // Result position (needed for loop bound — FIX B)
    const int tgt_t = (int)(L_subject / 32);
    const int tgt_r = (int)(L_subject % 32);
    // Thread tgt_t processes row L_query-1 at k = L_query+tgt_t+1.
    // Loop runs until that step. No epilogue needed.
    const index_t k_stop = L_query + (index_t)tgt_t + 2;

    index_t counter = 1;
    value_t query_value = INFINITY;
    value_t new_query_value = cQuery[thid];
    if (thid == 0) query_value = new_query_value;
    if (thid == 0) penalty_here1 = (value_t)0;  // free start
    new_query_value = __shfl_down_sync(0xFFFFFFFF, new_query_value, 1, 32);

    // Pre-loop: first anti-diagonal
        penalty_temp0 = penalty_here0;
        penalty_here0 = (query_value-SV0)*(query_value-SV0)+min(penalty_left,min(penalty_here0,penalty_diag));
        penalty_temp1 = INFINITY;
        penalty_here1 = (query_value-SV1)*(query_value-SV1)+min(penalty_here0,min(penalty_here1,penalty_temp0));
        penalty_temp0 = penalty_here2;
        penalty_here2 = (query_value-SV2)*(query_value-SV2)+min(penalty_here1,min(penalty_here2,penalty_temp1));
        penalty_temp1 = penalty_here3;
        penalty_here3 = (query_value-SV3)*(query_value-SV3)+min(penalty_here2,min(penalty_here3,penalty_temp0));
        penalty_temp0 = penalty_here4;
        penalty_here4 = (query_value-SV4)*(query_value-SV4)+min(penalty_here3,min(penalty_here4,penalty_temp1));
        penalty_temp1 = penalty_here5;
        penalty_here5 = (query_value-SV5)*(query_value-SV5)+min(penalty_here4,min(penalty_here5,penalty_temp0));
        penalty_temp0 = penalty_here6;
        penalty_here6 = (query_value-SV6)*(query_value-SV6)+min(penalty_here5,min(penalty_here6,penalty_temp1));
