    value_t penalty_here23 = INFINITY;
    value_t penalty_here24 = INFINITY;
    value_t penalty_here25 = INFINITY;
    value_t penalty_here26 = INFINITY;
    value_t penalty_here27 = INFINITY;
    value_t penalty_here28 = INFINITY;
    value_t penalty_here29 = INFINITY;
    value_t penalty_here30 = INFINITY;
    value_t penalty_here31 = INFINITY;
    value_t penalty_here32 = INFINITY;
    value_t penalty_here33 = INFINITY;
    value_t penalty_left = INFINITY;
    value_t penalty_diag = 0;
    value_t penalty_temp0, penalty_temp1;

    if (thid == 0) {
        penalty_diag = INFINITY;
        penalty_here0 = INFINITY;
        penalty_here1 = INFINITY;
        penalty_here2 = INFINITY;
        penalty_here3 = INFINITY;
        penalty_here4 = INFINITY;
        penalty_here5 = INFINITY;
        penalty_here6 = INFINITY;
