        penalty_temp1 = penalty_here61;
        penalty_here61 = (query_value-SV61)*(query_value-SV61)+min(penalty_here60,min(penalty_here61,penalty_temp0));
        penalty_here62 = (query_value-SV62)*(query_value-SV62)+min(penalty_here61,min(penalty_here62,penalty_temp1));
